import React, { Component } from "react";
import Pagination2 from "react-js-pagination";
import { FormattedMessage } from "react-intl";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import Loader from "react-loader-spinner";
import "react-dates/lib/css/_datepicker.css";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import { fetchPOSacquirerSummaryItem } from "../../../actions/filesets";

// components
import {
	Card,
	CardBody,
	CardHeader,
	Col,
	Row,
	Table,
	// Button
} from "reactstrap";
import PostingTable from "../../../components/PostingTable";
import PostingTableHeader from "../../../components/PostingTableHeader";

// utility functions
// import { setTableHeader } from "../../../Utils/utilityFunctions";

class POSAcuqirersDetails extends Component {
	constructor (props) {
		super(props);
		this.state = {
			activePage   : 1,
			isError404   : false,
			isError400   : false,
			selectedCode : "",
		};
		this.handlePageChange = this.handlePageChange.bind(this);
	}

	static getDerivedStateFromProps (props, state) {
		if (props.match.params.page !== state.activePage) {
			return {
				activePage : parseInt(props.match.params.page),
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchPOSacquirerSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
	}

	componentDidUpdate (prevProps) {
		if (this.props.match.params.page !== prevProps.match.params.page) {
			this.props.fetchPOSacquirerSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
		}

		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchPOSacquirerSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
		}

		if (prevProps.match.params.date !== this.props.match.params.date) {
			this.props.fetchPOSacquirerSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
		}
	}

	handlePageChange = (pageNumber) => {
		this.props.history.push(`/downstream/logs/pos-acquirers/${this.props.match.params.date}/${pageNumber}`);
		this.setState({ activePage: pageNumber });
	};

	render () {
		const POSacquirerLogSummaryItemHeader = [
			"Channel Name",
			"Ser No",
			"Ps Name",
			"I018 Merch Type",
			"I031 Arn",
			"I037 Ret Ref Num",
			"I038 Auth Id",
			"I039 Resp Cd",
			"I041 Pos Id",
			"I043A Merch Name",
			"I043B Merch City",
			"I043C Merch Cnt",
			"I000 Msg Type",
			"Pan",
			"I003 Proc Code",
			"I004 Amt Trxn",
			"I005 Amt Settle",
			"I006 Amt Bill",
			"I007 Load Date",
			"I013 Trxn Date",
			"I042 Merch Id",
			"I048 Text Data",
			"I049 Cur Trxn",
			"I050 Cur Settle",
			"I051 Cur Bill",
			"Center Amount",
			"Installment Type",
			"Amount",
			"Tip Amount",
			"Bill Tip Amount",
			"Com Amount",
			"Orig Com Amount",
			"Post Date",
			"Post Time Stamp",
			"St General",
		];

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						<Card>
							<CardHeader>
								<i className='fa fa-table' aria-hidden='true' />
								<FormattedMessage
									id='POS Aquirers Summary Table'
									defaultMessage='POS Aquirers Summary Table'
								/>
							</CardHeader>
							<CardBody>
								{/* Handle Loading */}
								{!this.props.posAcquirerSummaryItem &&
								!this.props.posAcquirerSummaryItemError && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{/* Handle Error 404 */}
								{this.props.posAcquirerSummaryItem &&
								this.props.posAcquirerSummaryItem.content &&
								this.props.posAcquirerSummaryItem.content.length === 0 && (
									<div className={"d-flex justify-content-center align-items-center text-danger"}>
										<p>
											<FormattedMessage
												id={"No POS acquirer entries available"}
												defaultMessage={"No POS acquirer entries available"}
											/>
										</p>
									</div>
								)}

								{/* Handle All Error 400 */}
								{!this.props.posAcquirerSummaryItem &&
								this.props.posAcquirerSummaryItemError &&
								this.props.posAcquirerSummaryItemError.response.data === "" && (
									<div className={"d-flex justify-content-center align-items-center text-danger"}>
										<p>
											<FormattedMessage
												id='Error! Unable to load entries'
												defaultMessage='Error! Unable to load entries'
											/>
										</p>
									</div>
								)}

								{/* show table only if there is no error. */}
								{!this.props.posAcquirerSummaryItemError &&
								this.props.posAcquirerSummaryItem &&
								this.props.posAcquirerSummaryItem.content.length > 0 && (
									<Table
										hover
										bordered
										striped
										responsive
										size='sm'
										className='table-outline mb-0 d-sm-table'
										style={{ minWidth: "670%", textTransform: "capitalize" }}
									>
										<thead className='thead-light'>
											<PostingTableHeader
												// headerPayload={
												// 	this.props.posAcquirerSummaryItem ? (
												// 		setTableHeader(this.props.posAcquirerSummaryItem.content)
												// 	) : (
												// 		[]
												// 	)
												// }
												headerPayload={POSacquirerLogSummaryItemHeader}
												headerType={"array"}
											/>
										</thead>
										<tbody>
											<PostingTable
												tableName='pos-acquirersLogSummary'
												dataRecords={
													this.props.posAcquirerSummaryItem ? (
														this.props.posAcquirerSummaryItem.content
													) : (
														[]
													)
												}
											/>
										</tbody>
									</Table>
								)}

								{this.props.posAcquirerSummaryItem ? (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={this.props.posAcquirerSummaryItem.size}
											totalItemsCount={
												(this.props.posAcquirerSummaryItem &&
													this.props.posAcquirerSummaryItem.totalElements) ||
												null
											}
											pageRangeDisplayed={20}
											onChange={this.handlePageChange}
										/>
									</nav>
								) : (
									""
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		posAcquirerSummaryItem      : state.fileSets.posAcquirerSummaryItem,
		posAcquirerSummaryItemError : state.fileSets.posAcquirerSummaryItemError,
		selectedAffiliateCode       : state.fileSets.selectedAffiliateCode,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchPOSacquirerSummaryItem,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(POSAcuqirersDetails);
